package com.budgetwise.model;

import java.math.BigDecimal;
import java.util.Optional;

/**
 * Contextual recommendation generated by the intelligent decision-support advisor.
 */
public record SavingsRecommendation(
        String headline,
        String detailedRationale,
        BigDecimal recommendedCut,
        Optional<FinancialGoal> impactedGoal,
        RecommendationPriority priority
) {
    @Override
    public String toString() {
        return String.format("[%s] %s -> %s (Cut: %s)", priority, headline, detailedRationale, recommendedCut);
    }
}
